import React, { useEffect } from "react";
import { Link } from "react-router-dom";
import $ from "jquery";

function Layout({ children }) {
  useEffect(() => {
    // AdminLTE initialization
    if (window.AdminLTE) {
      window.AdminLTE.init();
    }
    // Optional: trigger sidebar treeview toggle
    $(".nav-sidebar .has-treeview").each(function () {
      $(this).treeview();
    });
  }, []);

  return (
    <div className="wrapper">
      {/* Navbar */}
      <nav className="main-header navbar navbar-expand navbar-white navbar-light">
        <ul className="navbar-nav">
          <li className="nav-item">
            <Link to="/" className="nav-link">Dashboard</Link>
          </li>
          <li className="nav-item">
            <Link to="/users" className="nav-link">Users</Link>
          </li>
          <li className="nav-item">
            <Link to="/departments" className="nav-link">Departments</Link>
          </li>
        </ul>
      </nav>

      {/* Sidebar */}
      <aside className="main-sidebar sidebar-dark-primary elevation-4">
        <a href="/" className="brand-link">
          <span className="brand-text font-weight-light">ORA Admin</span>
        </a>
        <div className="sidebar">
          <nav className="mt-2">
            <ul className="nav nav-pills nav-sidebar flex-column" data-widget="treeview">
              <li className="nav-item">
                <Link to="/users" className="nav-link">Users</Link>
              </li>
              <li className="nav-item">
                <Link to="/departments" className="nav-link">Departments</Link>
              </li>
            </ul>
          </nav>
        </div>
      </aside>

      {/* Content */}
      <div className="content-wrapper">
        <section className="content">
          <div className="container-fluid">{children}</div>
        </section>
      </div>
    </div>
  );
}

export default Layout;
